'use strict';
const $=id=>document.getElementById(id),esc=x=>String(x??'UNKNOWN').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=new URLSearchParams(location.search).get('date')||'2026-10-27';let manifest,group='all',limit=100,token=0;const verified=new Map();
async function check(path,sha){if(verified.get(path)===sha)return;const res=await fetch(path,{cache:'no-store'});if(!res.ok)throw Error(`${path} 无法读取`);const bytes=await res.arrayBuffer();const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),x=>x.toString(16).padStart(2,'0')).join('');if(hash!==sha)throw Error(`${path} 与本日冻结版本不一致；已阻止用后续刷新覆盖本日历史`);verified.set(path,sha)}
function clear(){++token;$('frameHost').replaceChildren();$('error').textContent=''}
function render(){const q=$('search').value.trim().toLowerCase(),only=$('withCharts').checked;const stocks=manifest.stocks.filter(s=>(group==='all'||s.sources.includes(group))&&(!only||s.details.length)&&(!q||(s.symbol+s.name).toLowerCase().includes(q)));$('counts').textContent=`匹配 ${stocks.length} 个唯一股票 · 显示 ${Math.min(limit,stocks.length)} 个`;$('stockList').innerHTML=stocks.slice(0,limit).map(s=>`<button class="stock" data-symbol="${esc(s.symbol)}">${esc(s.name)} · ${esc(s.symbol)}<span>${s.sources.map(id=>esc(manifest.groups.find(g=>g.id===id).title)).join(' / ')}</span><span>${s.details.length?'有交互详情':'仅来源索引，未绑定交互图'}</span></button>`).join('');$('more').hidden=limit>=stocks.length;for(const b of $('stockList').querySelectorAll('[data-symbol]'))b.onclick=()=>select(b.dataset.symbol);if(!stocks.length){clear();$('selection').textContent='没有匹配的索引；不是零研究或无机会。'}}
function select(symbol){clear();const s=manifest.stocks.find(x=>x.symbol===symbol);if(!s){$('selection').textContent='UNKNOWN：本日没有该股票身份';return}$('selection').innerHTML=`<h2>${esc(s.name)} ${esc(s.symbol)}</h2><p>本日来源：${s.sources.map(id=>esc(manifest.groups.find(g=>g.id===id).title)).join(' / ')}</p>${s.details.map((d,i)=>`<button data-detail="${i}">${esc(manifest.groups.find(g=>g.id===d.dataset).title)} · 打开固定模板</button>`).join(' ')}${s.details.length?'':'<p>仅归档来源身份与覆盖层级；没有绑定的交互图，不伪造“已看图”。原报告来源及摘要见上方各集合证据。</p>'}`;for(const b of $('selection').querySelectorAll('[data-detail]'))b.onclick=()=>openDetail(s,s.details[Number(b.dataset.detail)]);if(s.details.length)openDetail(s,s.details.find(d=>d.dataset===group)||s.details[0])}
async function openDetail(s,d){clear();const mine=token;$('error').textContent='正在校验本日独立归档数据、图与模板版本…';try{await check(d.data,d.data_sha256);const prefix=d.asset_prefix||'';if(d.chart_path)await check(d.chart_path,d.chart_sha256);if(d.review_path)await check(d.review_path,d.review_sha256);if(d.display_path)await check(d.display_path,d.display_sha256);const needed=d.required_assets||(d.dataset==='history18'?['history18.html','app.js','styles.css']:[d.page,prefix+'live85.js',prefix+'chart85.js',prefix+'modules85.js',prefix+'styles.css',...(d.dataset==='breakout41'?[prefix+'breakout41.config.js']:[])]);for(const p of needed){const a=manifest.frozen_assets.find(x=>x.path===p);if(!a)throw Error('冻结模板清单缺项');await check(a.path,a.sha256)}if(mine!==token)return;const frame=document.createElement('iframe');frame.className='detail-frame';frame.title=`${date} ${s.name} ${d.dataset} 固定个股工作台`;frame.src=d.page+'#'+encodeURIComponent(s.symbol);$('frameHost').append(frame);$('error').textContent='已核冻结版本。下方复用既有个股工作台，批次与报价以图旁标签为准。'}catch(e){if(mine===token){$('frameHost').replaceChildren();$('error').textContent=e.message}}}
async function init(){$('title').textContent=`${date} · 研究归档`;if(date!=='2026-10-27'){$('status').textContent='此日期未归档：没有已交付归档回执，不表示0只研究。';return}try{const revision=new URLSearchParams(location.search).get('revision')||'r3';if(!['r1','r2','r3'].includes(revision))throw Error('未知研究修订；不回退冒充已有版本');const r=await fetch(revision==='r1'?'research-2026-10-27.json':revision==='r2'?'research-2026-10-27-r2.json':'research-2026-10-27-r3.json');if(!r.ok)throw Error('归档索引无法读取');manifest=await r.json();if(manifest.research_date!==date)throw Error('研究日期不一致');$('content').hidden=false;if(revision==='r3')document.querySelector('.notice').textContent='研究日2026-10-27；126个股中123图/白黄BBI/分位已更新D27，002086/002249/688306保留D26+UNKNOWN。原关键K锚与来源池仍D26；报价为D27已审收盘后快照，非class1复权语义UNVERIFIED，不等交易认证。';$('revisions').innerHTML='<a href="daily.html?date=2026-10-27&revision=r3">r3 D27图指标更新</a> · <a href="daily.html?date=2026-10-27&revision=r2">r2 结构修订</a> · <a href="daily.html?date=2026-10-27&revision=r1">r1 初版冻结</a> · <a href="archive/2026-10-27/r2/README.txt" target="_blank" rel="noopener">41结构研究报告</a><br>当前 '+esc(revision)+'；新增研究结论，不新增股票人数。'+(revision==='r3'?'<br>123只已更新D27图/线/分位；3只仍D26待核。接入 UTC '+esc(manifest.revisions[2].integrated_utc):revision==='r2'?'<br>研究源 UTC '+esc(manifest.revisions[1].source_created_utc)+'；本次接入 UTC '+esc(manifest.revisions[1].integrated_utc):'');$('status').textContent=`${manifest.stocks.length} 个去重来源身份 · 126只本轮交互图详情 + 原18历史批次 · 不将初筛、监控或涨幅榜冒充图审/候选`;$('scopes').innerHTML=manifest.groups.map(g=>`<article class="card"><h2>${esc(g.title)} · ${g.count}</h2><p>${esc(g.scope)}</p><p class="muted">${esc(g.batch)}</p><details><summary>冻结来源与SHA</summary><p>${esc(g.source)}</p><code>${esc(g.source_sha256)}</code></details></article>`).join('');$('groups').innerHTML='<button data-group="all" class="active">全部来源</button>'+manifest.groups.map(g=>`<button data-group="${esc(g.id)}">${esc(g.title)}</button>`).join('');for(const b of $('groups').querySelectorAll('button'))b.onclick=()=>{clear();group=b.dataset.group;limit=100;for(const x of $('groups').querySelectorAll('button'))x.classList.toggle('active',x===b);$('selection').textContent='请选择本集合股票';render()};$('search').oninput=()=>{limit=100;clear();$('selection').textContent='请选择搜索结果';render()};$('withCharts').onchange=()=>{limit=100;clear();$('selection').textContent='请选择股票';render()};$('more').onclick=()=>{limit+=100;render()};render();if(location.hash){let s;try{s=decodeURIComponent(location.hash.slice(1))}catch{throw Error('股票代码无效')}select(s)}}catch(e){$('error').textContent=e.message;$('content').hidden=true}}init();
